UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 17.00, seguimiento_sem2 = NULL, seguimiento_descripcion = 'Evaluación de patologías constructivas en la Casa de la Cultura de Santo Tomás: un diagnóstico técnico integral\nRenovación Integral, Accesibilidad Universal y Recuperación del Espacio Público – Parque Lineal Ciudad del Parque (Tramo 1)\nMonumentalidad con Alma Comunitaria: Hito Urbano Participativo en la carrera 16 entre calle 33B y calle 41 en el municipio de Soledad\nVivienda Multifamiliar en Barranquilla: el caso de la Ciudadela 20 de Julio\nHub de Bienestar y Encuentro Docente\nDiseño Aula-Laboratorio Proyección de la Escuela Real\nPropuesta de Sistema de Transporte Masivo Metropolitano: Hacia un sistema de movilidad integrado, eficiente y sostenible para la ciudad\nDiseño de Integración del Campus Uniatlántico\nConurbación Emergente en el Corredor Cartagena–Barranquilla: Tramo del Departamento de Bolívar' WHERE formulacion_id = @base+21 AND facultad_id = 1;
UPDATE formulacion_distribucion_facultad_144 SET seguimiento_sem1 = 12.00, seguimiento_sem2 = NULL, seguimiento_descripcion = 'Proyectos presentados por los semilleros de investigación de la Facultad de Bellas Artes en el Encuentro Regional de Semilleros de Investigación (2026):\n\n1. Estado de la danza en las Islas de San Andrés y Providencia en el siglo XXI | Semillero: Corpoedu | Programa: Danza | Coordinadora: Mónica Lindo de las Salas.\n\n2. El Carnaval viste de gala: caracterización de los espectáculos de coronación y lecturas del bando de las reinas del Carnaval de Barranquilla desde el año 2000 al 2026 | Semillero: Corpoedu | Programa: Danza | Coordinadora: Mónica Lindo de las Salas.\n\n3. El Carnaval sigue: una propuesta pedagógica y de intervención comunitaria para la apropiación activa del patrimonio cultural en la infancia del municipio de Sabanagrande, Atlántico | Semillero: Corpoedu | Programa: Danza | Coordinadora: Mónica Lindo de las Salas.\n\n4. Rodillones: identidad de un pueblo a la orilla del Magdalena | Semillero: Corpoedu | Programa: Danza | Coordinadora: Mónica Lindo de las Salas.\n\n5. El Eco del Vacío | Semillero: CREANDO | Programa: Danza | Coordinadora: Tania Iglesias.\n\n6. MetaCuerpo | Semillero: CREANDO | Programa: Danza | Coordinadora: Tania Iglesias.\n\n7. Plumas de Ocaso | Semillero: CREANDO | Programa: Danza | Coordinadora: Tania Iglesias.\n\n8. ¿Corcoveas? Una tradición heredada a mi piel | Semillero: CREANDO | Programa: Danza | Coordinadora: Tania Iglesias.\n\n9. Ejercicios de técnica vocal para el nivel inicial a partir de canciones del género vallenato | Semillero: Semillero de Investigación en Música del Caribe (SIMUCA) | Programa: Licenciatura en Música | Coordinadora: Ángela de Jesús Marín Niebles.\n\n10. Expresiones musicales pianísticas del patrimonio cultural del Atlántico-Colombia y su impacto social | Semillero: Musiarte | Programa: Licenciatura en Música | Coordinadora: Yamira Rodríguez Núñez.\n\n11. Contracartografías sonoras: prácticas estéticas y contraculturales en la escena musical alternativa de Barranquilla | Semillero: Xperimenta | Programa: Artes Plásticas | Coordinador: Houmehr Etminani Moslehi.\n\n12. "Soy": Cuerpo, género y violencia simbólica en corporalidades disidentes | Semillero: CUERPAS (Cuerpos, Archivos, Performance, Fiestas) | Programa: Danza | Coordinador: Danny Armando González Cueto.\n\nTotal de proyectos presentados: 12.' WHERE formulacion_id = @base+21 AND facultad_id = 2;
